#include <cstdio>
#include <algorithm>
int main(){for(auto shape:{std::pair<int,int>{3,8},{4,7},{5,6}}){auto [a,b]=shape;int total=0;for(int k=1;k<(1<<((a-1)*(b-1)));k+=2){int adj[20]={};for(int i=0;i<a-1;i++){int row=(k>>(i*(b-1)))&((1<<(b-1))-1);adj[i]=(row|(__builtin_parity((unsigned)row)<<(b-1)))<<a;adj[a-1]^=adj[i];}for(int i=0;i<a;i++)for(int j=0;j<b;j++)if(adj[i]>>(a+j)&1)adj[a+j]|=1<<i;adj[0]^=1<<a;adj[a]^=1;bool yes=false;for(int h=0;h<a+b&&!yes;h++){int ban=adj[h]|(1<<h);if(ban&(1|(1<<a)))continue;int reach=1,front=1;while(front){int u=__builtin_ctz((unsigned)front);front&=front-1;int extend=adj[u]&~(ban|reach);reach|=extend;front|=extend;}yes=reach&(1<<a);}if(!yes){printf("FAIL %d %d %d\n",a,b,k);return 1;}total++;}printf("K%d,%d: %d rooted graphs passed\n",a,b,total);}}
